#!/usr/bin/env python3
"""Stage S, round 11: exact S6/S7 constants and all extremizing orbits.

Run with Python 3 standard library only, without -O.
All certificate data are explicit, uncompressed integer lists. No numerical
solver, previous certificate, network, or external data file is used.
The accompanying report proves the mathematical implications of each check.
"""
from fractions import Fraction as F
from functools import lru_cache
from collections import Counter
import itertools, math, json, time
if not __debug__: raise RuntimeError('Run without Python -O.')
SCALE = 10**50

class Z:
    __slots__=('r','i')
    def __init__(self,r=0,i=0):
        if isinstance(r,Z):self.r,self.i=r.r,r.i
        elif isinstance(r,(tuple,list)):self.r,self.i=F(r[0]),F(r[1])
        else:self.r,self.i=F(r),F(i)
    def __add__(a,b):
        b=Z(b);return Z(a.r+b.r,a.i+b.i)
    __radd__=__add__
    def __neg__(a):return Z(-a.r,-a.i)
    def __sub__(a,b):return a+-Z(b)
    def __rsub__(a,b):return Z(b)+-a
    def __mul__(a,b):
        b=Z(b);return Z(a.r*b.r-a.i*b.i,a.r*b.i+a.i*b.r)
    __rmul__=__mul__
    def conj(a):return Z(a.r,-a.i)
    def norm2(a):return a.r*a.r+a.i*a.i
    def __truediv__(a,b):
        b=Z(b);c=a*b.conj();return Z(c.r/b.norm2(),c.i/b.norm2())
    def __eq__(a,b):
        b=Z(b);return a.r==b.r and a.i==b.i

def dot(a,b):return sum((x*y for x,y in zip(a,b)),Z())

def adj(A):return [[A[j][i].conj() for j in range(len(A))] for i in range(len(A[0]))]

def mm(A,B):return [[dot(row,col) for col in zip(*B)] for row in A]

def eye(n):return [[Z(int(i==j)) for j in range(n)] for i in range(n)]

def inverse(A):
 n=len(A);M=[list(row)+e for row,e in zip(A,eye(n))]
 for j in range(n):
  k=next(i for i in range(j,n) if M[i][j]!=0);M[j],M[k]=M[k],M[j];d=M[j][j];M[j]=[a/d for a in M[j]]
  for i in range(n):
   if i!=j:
    z=M[i][j];M[i]=[a-z*b for a,b in zip(M[i],M[j])]
 return [row[n:] for row in M]

def positive(A):
 n=len(A);assert all(A[i][j]==A[j][i].conj() for i in range(n) for j in range(n))
 L=[[Z() for _ in range(n)] for _ in range(n)];ds=[]
 for j in range(n):
  assert A[j][j].i==0
  d=A[j][j].r-sum((L[j][k].norm2()*ds[k] for k in range(j)),F())
  assert d>0,('nonpositive exact LDL pivot',j,d)
  ds.append(d);L[j][j]=Z(1)
  for i in range(j+1,n):L[i][j]=(A[i][j]-sum((L[i][k]*L[j][k].conj()*ds[k] for k in range(j)),Z()))/d
 return min(ds)

def ceildiv(a, b):
    return -((-a)//b)

class I:
    __slots__ = ('lo', 'hi')

    def __init__(self, lo, hi=None):
        self.lo = int(lo)
        self.hi = int(lo if hi is None else hi)
        assert self.lo <= self.hi

    @staticmethod
    def rational(n, d=1):
        return I(n*SCALE//d, ceildiv(n*SCALE, d))

    def __add__(a, b):
        return I(a.lo+b.lo, a.hi+b.hi)

    def __neg__(a):
        return I(-a.hi, -a.lo)

    def __sub__(a, b):
        return a+(-b)

    def __mul__(a, b):
        v = [a.lo*b.lo, a.lo*b.hi, a.hi*b.lo, a.hi*b.hi]
        return I(min(v)//SCALE, ceildiv(max(v), SCALE))

    def __truediv__(a, b):
        if b.hi < 0:
            return (-a)/(-b)
        assert b.lo > 0
        v = [(x*SCALE, y) for x in [a.lo, a.hi] for y in [b.lo, b.hi]]
        return I(min(n//d for n, d in v), max(ceildiv(n, d) for n, d in v))

    def square(a):
        lower = 0 if a.lo <= 0 <= a.hi else min(a.lo*a.lo, a.hi*a.hi)
        upper = max(a.lo*a.lo, a.hi*a.hi)
        return I(lower//SCALE, ceildiv(upper, SCALE))

    def sqrt(a):
        assert a.lo >= 0
        lo = math.isqrt(a.lo*SCALE)
        hi = math.isqrt(a.hi*SCALE)
        if hi*hi < a.hi*SCALE:
            hi += 1
        return I(lo, hi)

def cadd(a, b):
    return a[0]+b[0], a[1]+b[1]

def csub(a, b):
    return a[0]-b[0], a[1]-b[1]

def cconj(a):
    return a[0], -a[1]

def cmul(a, b):
    return a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0]

def crealmul(a, b):
    return a[0]*b, a[1]*b

def cnorm2(a):
    return a[0].square()+a[1].square()

def qi(n,d=1):return I.rational(n,d)

@lru_cache(None)
def exact_pi():
 def atan(q):
  p=sum((F((-1)**j,(2*j+1)*q**(2*j+1)) for j in range(50)),F())
  e=F(1,101*q**101)
  a=qi(p.numerator,p.denominator);b=qi((p+e).numerator,(p+e).denominator)
  return I(a.lo,b.hi)
 return qi(16)*atan(5)-qi(4)*atan(239)

def interval_positive(A):
 n=len(A);L=[[(ZERO,ZERO) for _ in range(n)] for _ in range(n)];ds=[]
 for j in range(n):
  d=A[j][j][0]
  for k in range(j):d=d-cnorm2(L[j][k])*ds[k]
  if d.lo<=0:return False
  ds.append(d);L[j][j]=(ONE,ZERO)
  for i in range(j+1,n):
   z=A[i][j]
   for k in range(j):z=csub(z,crealmul(cmul(L[i][k],cconj(L[j][k])),ds[k]))
   L[i][j]=(z[0]/d,z[1]/d)
 return True

ZERO=I(0)
ONE=I(SCALE)
TWO=I(2*SCALE)

class AD:
 __slots__=('v','g')
 D=0
 def __init__(self,v,g=None):self.v=v if isinstance(v,I) else qi(v);self.g=[ZERO]*AD.D if g is None else g
 def __add__(a,b):
  if not isinstance(b,AD):b=AD(b)
  return AD(a.v+b.v,[x+y for x,y in zip(a.g,b.g)])
 __radd__=__add__
 def __neg__(a):return AD(-a.v,[-x for x in a.g])
 def __sub__(a,b):return a+-asAD(b)
 def __rsub__(a,b):return asAD(b)+-a
 def __mul__(a,b):
  b=asAD(b);return AD(a.v*b.v,[x*b.v+a.v*y for x,y in zip(a.g,b.g)])
 __rmul__=__mul__
 def __truediv__(a,b):
  b=asAD(b);return AD(a.v/b.v,[(x*b.v-a.v*y)/b.v.square() for x,y in zip(a.g,b.g)])
 def square(a):return AD(a.v.square(),[qi(2)*a.v*x for x in a.g])
 def sqrt(a):
  r=a.v.sqrt();return AD(r,[x/(qi(2)*r) for x in a.g])

def asAD(x):return x if isinstance(x,AD) else AD(x)

@lru_cache(None)
def center_trig(mid):
 x=F(mid,SCALE);ss=F();cc=F()
 for j in range(55):ss+=(-1)**j*x**(2*j+1)/math.factorial(2*j+1);cc+=(-1)**j*x**(2*j)/math.factorial(2*j)
 er=abs(x)**110/math.factorial(110)
 def enc(z):
  a=qi((z-er).numerator,(z-er).denominator);b=qi((z+er).numerator,(z+er).denominator);return I(a.lo,b.hi)
 return enc(ss),enc(cc)

def itrign(a):
 mid=(a.lo+a.hi)//2;rad=max(mid-a.lo,a.hi-mid);s,c=center_trig(mid)
 return I(s.lo-rad,s.hi+rad),I(c.lo-rad,c.hi+rad)

def adtrig(a):
 s,c=itrign(a.v);return AD(s,[c*x for x in a.g]),AD(c,[-s*x for x in a.g])

def stationarity_system(n,box):
 m=n+1;d=4*n;AD.D=d
 xx=[]
 for j,a in enumerate(box):xx.append(AD(a,[ONE if k==j else ZERO for k in range(d)]))
 zero=AD(0);one=AD(1)
 p=[(xx[k],zero if k<2 else xx[m+k-2]) for k in range(m)]
 th=xx[2*m-2:2*m-2+n];lam=xx[-n:]
 rows=[];pv=[];dv=[]
 for t in th:
  sn,cs=adtrig(t);zz=(cs,sn);row=[(one,zero)]
  for _ in range(n):row.append(cmul(row[-1],zz))
  rows.append(row);pval=(zero,zero);dval=(zero,zero)
  for k in range(m):
   prod=cmul(p[k],row[k]);pval=cadd(pval,prod);dval=cadd(dval,crealmul(prod,AD(k)))
  pv.append(pval);dv.append(dval)
 moments=[]
 for k in range(m):
  a=(zero,zero)
  for j in range(n):a=cadd(a,crealmul(cmul(cconj(pv[j]),rows[j][k]),lam[j]))
  rho=cnorm2(p[k]).sqrt();a=csub(a,(p[k][0]/rho,-p[k][1]/rho));moments.append(a)
 out=[z[0] for z in moments]+[z[1] for z in moments[2:]]+[cnorm2(z)-1 for z in pv]+[-cmul(cconj(z),d)[1] for z,d in zip(pv,dv)]
 assert len(out)==d
 return [z.v for z in out],[z.g for z in out]

def krawczyk(n,point,Rnums,pden=10**15,rden=10**12):
 d=4*n;x=[qi(z,pden) for z in point];rad=qi(1,10**9)
 X=[a+I(-rad.hi,rad.hi) for a in x];f0,_=stationarity_system(n,x);_,J=stationarity_system(n,X)
 R=[[qi(v,rden) for v in row] for row in Rnums]
 E=[[((ONE if i==j else ZERO)-sumI(R[i][k]*J[k][j] for k in range(d))) for j in range(d)] for i in range(d)]
 maxq=0;out=[]
 for i in range(d):
  rr=sum(max(abs(v.lo),abs(v.hi)) for v in E[i]);maxq=max(maxq,rr)
  center=x[i]-sumI(R[i][j]*f0[j] for j in range(d));er=ceildiv(rr*rad.hi,SCALE)
  z=center+I(-er,er)
  assert X[i].lo<z.lo<=z.hi<X[i].hi,('Krawczyk inclusion',n,i,X[i].lo,z.lo,z.hi,X[i].hi)
  out.append(z)
 assert maxq<SCALE//2
 for refinement in range(3):
  ctr=[I((z.lo+z.hi)//2) for z in out]
  fctr,_=stationarity_system(n,ctr);_,JJ=stationarity_system(n,out)
  EE=[[((ONE if i==j else ZERO)-sumI(R[i][k]*JJ[k][j] for k in range(d))) for j in range(d)] for i in range(d)]
  newer=[]
  for i in range(d):
   z=ctr[i]-sumI(R[i][j]*fctr[j] for j in range(d))+sumI(EE[i][j]*(out[j]-ctr[j]) for j in range(d))
   newer.append(I(max(out[i].lo,z.lo),min(out[i].hi,z.hi)))
  out=newer
 print('PASS: degree',n,'stationary root exists uniquely in the rational box; contraction <1/2')
 return out

def sumI(v):
 out=ZERO
 for x in v:out=out+x
 return out

def cx(x):return x if isinstance(x,tuple) else (x,ZERO)

def cadj(A):return [[cconj(A[j][i]) for j in range(len(A))] for i in range(len(A[0]))]

def cmm(A,B):return [[csum(cmul(x,y) for x,y in zip(row,col)) for col in zip(*B)] for row in A]

def csum(v):
 out=(ZERO,ZERO)
 for x in v:out=cadd(out,x)
 return out

def cmatrix_add(A,B):return [[cadd(x,y) for x,y in zip(row,col)] for row,col in zip(A,B)]

def cmatrix_sub(A,B):return [[csub(x,y) for x,y in zip(row,col)] for row,col in zip(A,B)]

def cscale(A,k):return [[crealmul(x,k) for x in row] for row in A]

def cieye(n):return [[(ONE if i==j else ZERO,ZERO) for j in range(n)] for i in range(n)]

def cdivide(a,b):
 c=cmul(a,cconj(b));d=cnorm2(b);return c[0]/d,c[1]/d

def ciinverse(A):
 n=len(A);M=[list(row)+e for row,e in zip(A,cieye(n))]
 for j in range(n):
  k=max(range(j,n),key=lambda i:abs(M[i][j][0].lo+M[i][j][0].hi)+abs(M[i][j][1].lo+M[i][j][1].hi))
  M[j],M[k]=M[k],M[j];d=M[j][j];M[j]=[cdivide(v,d) for v in M[j]]
  for i in range(n):
   if i!=j:
    z=M[i][j];M[i]=[csub(a,cmul(z,b)) for a,b in zip(M[i],M[j])]
 return [row[n:] for row in M]

def rmm(A,B):return [[sumI(x*y for x,y in zip(row,col)) for col in zip(*B)] for row in A]

def rt(A):return [list(row) for row in zip(*A)]

def rinverse(A):return [[z[0] for z in row] for row in ciinverse([[cx(z) for z in row] for row in A])]

def rvec(A,b):return [sumI(x*y for x,y in zip(row,b)) for row in A]

def couter(a,b):return [[cmul(x,cconj(y)) for y in b] for x in a]

def ccoords(A):return [A[0][0][0],A[0][1][0],A[0][1][1]]

def cfrob(A):return sumI(cnorm2(z) for row in A for z in row)

def realtrace(A):return sumI(A[i][i][0] for i in range(len(A)))

def circle_row(t,n):
 s,c=itrign(t);z=(c,s);row=[(ONE,ZERO)]
 for _ in range(n):row.append(cmul(row[-1],z))
 return row

def cconv(a,b):
 out=[(ZERO,ZERO) for _ in range(len(a)+len(b)-1)]
 for i,x in enumerate(a):
  for j,y in enumerate(b):out[i+j]=cadd(out[i+j],cmul(x,y))
 return out

def verify_reversal_symmetry(n,root,point,beta_num):
 m=n+1;p=[(root[k],ZERO if k<2 else root[m+k-2]) for k in range(m)]
 rho=[cnorm2(z).sqrt() for z in p];gam=(p[n][0]/rho[n],-p[n][1]/rho[n])
 temp=cmul(gam,p[n-1]);eta=(temp[0]/rho[n-1],-temp[1]/rho[n-1])
 beta0=qi(beta_num,10**15);sn,cs=itrign(beta0);dist=cnorm2(csub(eta,(cs,sn))).sqrt()
 assert dist.hi<qi(1,10**6).lo
 beta=beta0+I(-2*dist.hi,2*dist.hi)
 pp=[];power=(ONE,ZERO)
 for k in range(m):pp.append(cmul(cmul(gam,power),p[n-k]));power=cmul(power,eta)
 th=root[2*m-2:2*m-2+n];lam=root[-n:];pairs=[]
 for t,w in zip(th,lam):
  z=-beta-t
  if z.hi<0:z=z+qi(2)*exact_pi()
  else:assert z.lo>0
  pairs.append((z,w))
 pairs.sort(key=lambda z:z[0].lo+z[0].hi)
 transformed=[z[0] for z in pp]+[z[1] for z in pp[2:]]+[z[0] for z in pairs]+[z[1] for z in pairs]
 assert len(transformed)==4*n
 radius=qi(1,10**9)
 for z,num in zip(transformed,point):
  center=qi(num,10**15);assert center.lo-radius.hi<z.lo<=z.hi<center.hi+radius.hi
 print('PASS: degree',n,'candidate fixed by reversal after phase normalization; a reciprocal representative exists')

def ri(Fvalue):
 f=F(Fvalue);return qi(f.numerator,f.denominator)

def rdot(a,b):return sumI(x*y for x,y in zip(a,b))

def radd(a,b):return [x+y for x,y in zip(a,b)]

def rscale(a,b):return [x*b for x in a]

def rmatvec(A,b):return [rdot(row,b) for row in A]

def rsubm(A,B):return [[x-y for x,y in zip(a,b)] for a,b in zip(A,B)]

def eyeI(n):return [[ONE if i==j else ZERO for j in range(n)] for i in range(n)]

def rp(A):return interval_positive([[(z,ZERO) for z in row] for row in A])

def frobsq(A):return sumI(x.square() for row in A for x in row)

def inormsq(a):return sumI(x.square() for x in a)

def multiplicity(inds):
 a=math.factorial(len(inds))
 for count in Counter(inds).values():a//=math.factorial(count)
 return a

def atom_certificate(n,item,rootitem):
 root=krawczyk(n,rootitem['point'],rootitem['R']);m=n+1;d=n-1;r=n
 p=[(root[k],ZERO if k<2 else root[m+k-2]) for k in range(m)]
 rho=[cnorm2(a).sqrt() for a in p];C=sumI(rho);th=root[2*m-2:2*m-2+n];lam=root[-n:]
 assert p[0][0].lo>0 and p[1][0].lo>0
 assert all(x.lo>0 for x in rho+lam)
 assert sumI(cnorm2(a) for a in p).hi<ONE.lo
 assert all(th[j].hi<th[j+1].lo for j in range(n-1)) and th[0].lo>0 and th[-1].hi<(qi(2)*exact_pi()).lo
 # The contact factor lemma in the report proves primal feasibility, and the
 # omitted two moment equations follow exactly from the displayed identities.
 b=[(a[0]/s,-a[1]/s) for a,s in zip(p,rho)]
 rows=[circle_row(t,n) for t in th]
 ww=[[cmul(z,cconj(bb)) for z,bb in zip(row,b)] for row in rows]
 def getmat(key):return [[qi(v,10**8) for v in row] for row in item[key]]
 A=getmat('A');L=getmat('L');PH=getmat('B');W=getmat('W');Wt=rt(W)
 assert len(A)==len(L)==n and len(A[0])==len(L[0])==d
 assert all(sum(row[k] for row in item['L'])==0 for k in range(d))
 phase=[[ZERO]*d]+PH+[[ZERO]*d]
 DD=[[[qi(k)*A[j][h]-phase[k][h] for h in range(d)] for k in range(m)] for j in range(r)]
 beta=[[[[DD[j][k][h]-DD[j][i][h] for h in range(d)] for k in range(m)] for i in range(m)] for j in range(r)]
 outer=[[[cmul(cconj(row[i]),row[k]) for k in range(m)] for i in range(m)] for row in ww]
 def rotated_re(a,order):return (a[0],-a[1],-a[0],a[1])[order%4]
 Q0=[[C*sumI(lam[j]*outer[j][i][k][0] for j in range(r)) for k in range(m)] for i in range(m)]
 S0=[[Q0[i][j]-ONE for j in range(m)] for i in range(m)]
 assert all(z.lo<=0<=z.hi for z in rmatvec(S0,rho))
 B0=rmm(rmm(Wt,S0),W);tau=qi(99,100)
 assert rp(rsubm(B0,[[tau if i==j else ZERO for j in range(n)] for i in range(n)]))
 Binv=rinverse(B0)
 tensors={}
 for order in (1,2,3):
  tensors[order]={}
  for inds in itertools.combinations_with_replacement(range(d),order):
   M=[]
   for i in range(m):
    row=[]
    for k in range(m):
     terms=[]
     for j in range(r):
      prod=ONE
      for h in inds:prod=prod*beta[j][i][k][h]
      z=lam[j]*rotated_re(outer[j][i][k],order)*prod
      for pos,h in enumerate(inds):
       prod=ONE
       for q,hh in enumerate(inds):
        if q!=pos:prod=prod*beta[j][i][k][hh]
       z=z+L[j][h]*rotated_re(outer[j][i][k],order-1)*prod
      terms.append(z)
     row.append(C*sumI(terms)/qi(math.factorial(order)))
    M.append(row)
   tensors[order][inds]=M
 def TS(order,inds):return tensors[order][tuple(sorted(inds))]
 K=[TS(1,(i,)) for i in range(d)]
 b1=rt([rmatvec(Wt,rmatvec(Ki,rho)) for Ki in K]);x1=[[-z for z in row] for row in rmm(Binv,b1)]
 h1=rmm(W,x1);hh=rt(h1)
 H=[[rdot(rho,rmatvec(TS(2,(i,j)),rho))-rdot([row[i] for row in b1],rmatvec(Binv,[row[j] for row in b1])) for j in range(d)] for i in range(d)]
 mu=qi(99,100)
 assert rp(rsubm(H,[[mu if i==j else ZERO for j in range(d)] for i in range(d)]))
 range_norms=[]
 physical_norms=[]
 for order in (1,2,3):
  rangeSq=ZERO;physSq=ZERO
  for inds,M in tensors[order].items():
   mult=qi(multiplicity(inds));rangeSq=rangeSq+mult*frobsq(rmm(rmm(Wt,M),W));physSq=physSq+mult*frobsq(M)
  range_norms.append(rangeSq);physical_norms.append(physSq)
 cubicSq=ZERO;cross2Sq=ZERO;cross3Sq=ZERO
 for inds in tensors[3]:
  val=rdot(rho,rmatvec(TS(3,inds),rho));cross=rmatvec(TS(3,inds),rho)
  add=ZERO;av=[ZERO]*m
  for a,bb,c in itertools.permutations(inds):
   add=add+qi(2)*rdot(hh[a],rmatvec(TS(2,(bb,c)),rho))+rdot(hh[a],rmatvec(K[bb],hh[c]))
   av=radd(av,rmatvec(TS(2,(a,bb)),hh[c]))
  val=val+add/qi(6);cross=rmatvec(Wt,radd(cross,rscale(av,qi(1,6))))
  mult=qi(multiplicity(inds));cubicSq=cubicSq+mult*val.square();cross3Sq=cross3Sq+mult*inormsq(cross)
 for inds in tensors[2]:
  a,bb=inds;cross=rmatvec(TS(2,inds),rho)
  cross=radd(cross,rscale(radd(rmatvec(K[a],hh[bb]),rmatvec(K[bb],hh[a])),qi(1,2)))
  cross=rmatvec(Wt,cross);cross2Sq=cross2Sq+qi(multiplicity(inds))*inormsq(cross)
 # Exact fourth-order Taylor remainder, using actual unit moduli of atoms.
 Ln=[inormsq(row).sqrt() for row in L];rem=[]
 for i in range(m):
  row=[]
  for k in range(m):
   terms=[]
   for j in range(r):
    normsq=inormsq(beta[j][i][k]);terms.append(lam[j]*normsq.square()/qi(24)+Ln[j]*normsq*normsq.sqrt()/qi(6))
   row.append(C*sumI(terms))
  rem.append(row)
 remsq=frobsq(rem)
 if n==6:
  bounds={'range':(6,19,9),'s2':21,'s3':13,'a':F(27,100),'g3':F(17,10),'c2':6,'c3':3,'rem4':48,'W':F(17,10),'R':F(1,16)}
 else:
  bounds={'range':(5,10,10),'s2':48,'s3':53,'a':F(21,20),'g3':8,'c2':8,'c3':9,'rem4':380,'W':F(89,100),'R':F(1,32)}
 def lessnorm(sq,bound):assert sq.hi<ri(F(bound)**2).lo,('norm bound',n,bound,sq.lo,sq.hi)
 for sq,lim in zip(range_norms,bounds['range']):lessnorm(sq,lim)
 lessnorm(physical_norms[1],bounds['s2']);lessnorm(physical_norms[2],bounds['s3'])
 lessnorm(frobsq(h1),bounds['a']);lessnorm(cubicSq,bounds['g3']);lessnorm(cross2Sq,bounds['c2']);lessnorm(cross3Sq,bounds['c3']);lessnorm(remsq,bounds['rem4'])
 wcap=ri(bounds['W']);assert rp(rsubm([[wcap.square() if i==j else ZERO for j in range(n)] for i in range(n)],rmm(Wt,W)))
 # Exact rational scalar inequalities for every radius <= R.
 R=bounds['R'];k,sb2,sb3=map(F,bounds['range']);s2=F(bounds['s2']);s3=F(bounds['s3']);a=F(bounds['a']);g3=F(bounds['g3']);c2=F(bounds['c2']);c3=F(bounds['c3']);e4=F(bounds['rem4']);wc=F(bounds['W']);ta=F(99,100);muu=F(99,100)
 ee=k*R+sb2*R**2+sb3*R**3+wc**2*e4*R**4
 lower=muu*R**2-g3*R**3-(2*a*s3+a*a*s2+a*a*s3*R+e4*(1+a*R)**2)*R**4
 cross=c2*R**2+c3*R**3+wc*s3*a*R**4+wc*e4*(1+a*R)*R**4
 assert ee<ta and lower>cross*cross/(ta-ee)
 assert all(w.lo>(norm*ri(R)).hi for w,norm in zip(lam,Ln))
 # Every Euclidean phase ball of radius R/4 lies in the certified ellipsoid.
 BB=[[F(v,10**8) for v in row] for row in item['B']];BI=inverse([[Z(v) for v in row] for row in BB]);BI=[[v.r for v in row] for row in BI]
 exact=mm(adj([[Z(v) for v in row] for row in BI]),[[Z(v) for v in row] for row in BI])
 positive([[Z(16*int(i==j))-exact[i][j] for j in range(d)] for i in range(d)])
 print('PASS: degree',n,'one-dimensional real kernel, moving positive atoms, phase ellipsoid radius',R,'Euclidean radius',R/4)
 print('PASS: degree',n,'range/phase preconditioning and all cubic/quartic remainder bounds')
 return root,b,C,BB,BI,bounds

def audit_real_dual_psd():
 b=[Z(1),Z(F(3,5),F(4,5)),Z(1)]
 T=[[Z(1),Z(F(5,3)),Z(1)],[Z(F(5,3)),Z(1),Z(F(5,3))],[Z(1),Z(F(5,3)),Z(1)]]
 Q=[[b[i]*T[i][j]*b[j].conj() for j in range(3)] for i in range(3)]
 assert all(z.r==1 for row in Q for z in row)
 assert 1-F(5,3)**2<0
 # rho=(1/2,1,1/2): the circle norm squared is 16/5 and J=2.
 # Its ratio squared is 5/4>1, so the fake diagonal-1 bound is invalid.
 assert F(4)/F(16,5)==F(5,4)>1
 print('PASS: T positive semidefinite is indispensable in the real-amplitude dual')

def audit_deficient_stationarity():
 for n,nums,den,ell,A,B,target in [(6,[2,6,-15,10,10,8,4],25,2,F(8,125),F(8,625),F(11,5)),(7,[1,2,3,3,3,-6,2,1],9,5,F(4,81),F(1,81),F(7,3))]:
  r=n-1;a=[F(v,den) for v in nums]
  assert all(v!=0 for v in a) and sum(abs(v) for v in a)==target
  assert A>2*abs(B)>0
  # Fourier coefficients of |z^r-1|^2 (A+Bz+B/z).
  expected={}
  for u,cu in ((0,F(2)),(r,F(-1)),(-r,F(-1))):
   for v,cv in ((0,A),(1,B),(-1,B)):expected[u+v]=expected.get(u+v,F())+cu*cv
  for h in range(n+1):assert int(h==0)-sum(a[k+h]*a[k] for k in range(n+1-h))==expected.get(h,F())
  mod=[sum(a[k] for k in range(s,n+1,r)) for s in range(r)]
  assert mod==[F(2,r)-int(k==ell) for k in range(r)]
  # At r-th roots of unity, P(1)=1 and P(zeta)=-zeta^ell otherwise.
  # lambda_0=1-2/r, lambda_j=2/r gives the exact coefficient signs.
  weightsum=1-F(2,r)+(r-1)*F(2,r)
  assert weightsum==target
  assert all((1-2*int(k%r==ell))==(1 if ak>0 else -1) for k,ak in enumerate(a))
 print('PASS: full coefficient support and positive stationary weights do not imply full contact; exact deficient examples in degrees 6 and 7')

def algebraic_box(n,root,rootitem):
 m=n+1;d=n-1;p=[(root[k],ZERO if k<2 else root[m+k-2]) for k in range(m)];th=root[2*m-2:2*m-2+n];lam=root[-n:];rho=[cnorm2(z).sqrt() for z in p]
 zz=[circle_row(t,1)[1] for t in th]
 groups=[[a[0] for a in p],[a[1] for a in p[2:]],[z[0] for z in zz],[z[1] for z in zz],lam,rho]
 def nearest(a):return (((a.lo+a.hi)//2)*10**15+SCALE//2)//SCALE
 centers=[[nearest(a) for a in row] for row in groups];rad=qi(1,10**12);boxes=[[qi(v,10**15)+I(-rad.hi,rad.hi) for v in row] for row in centers]
 for grow,brow in zip(groups,boxes):
  for a,B in zip(grow,brow):assert B.lo<a.lo<=a.hi<B.hi
 # Every solution in this rational box pulls back to the original trigonometric
 # box, where existence and uniqueness were already proved by contraction.
 original= [qi(v,10**15) for v in rootitem['point']];oldrad=qi(1,10**9)
 for B,ctr in zip(boxes[0]+boxes[1]+boxes[4],original[:2*n]+original[-n:]):assert ctr.lo-oldrad.hi<B.lo<=B.hi<ctr.hi+oldrad.hi
 for j,(xr,yi) in enumerate(zip(boxes[2],boxes[3])):
  t0=original[2*n+j];s,c=itrign(t0);dist=cnorm2(csub((xr,yi),(c,s))).sqrt();assert qi(2).hi*dist.hi//SCALE<oldrad.lo
 assert all(a.lo>0 for a in boxes[5]) and boxes[0][0].lo>0 and boxes[0][1].lo>0
 assert p[2][1].lo>0 or p[2][1].hi<0
 print('PASS: degree',n,'unique isolated real algebraic point in a rational box of dimension',6*n+1)
 return centers

assert exact_pi().hi < qi(22,7).lo
assert F(11,7)**60/F(math.factorial(60)) < F(1,SCALE)

@lru_cache(65536)
def general_root(N,t):
 assert isinstance(N,int) and N>0
 if N%2:return general_root(2*N,2*t)
 t%=N
 if t==0:return ONE,ZERO
 if 2*t==N:return -ONE,ZERO
 if 4*t==N:return ZERO,ONE
 if 4*t==3*N:return ZERO,-ONE
 if 2*t>N:return cconj(general_root(N,N-t))
 if 4*t>N:
  x,y=general_root(N,N//2-t);return -x,y
 x=qi(2*t,N)*exact_pi();xx=x.square();st=x;ct=ONE;ss=st;cc=ct
 for j in range(1,30):
  st=-(st*xx/qi((2*j)*(2*j+1)));ct=-(ct*xx/qi((2*j-1)*(2*j)))
  ss=ss+st;cc=cc+ct
 error=I(-1,1)
 return cc+error,ss+error

def audit_general_roots():
 for N in (7,14,48,56,64):
  for t in (0,1,N//3,N//2,N-1):
   z=general_root(N,t);arg=qi(2*t,N)*exact_pi();s,c=itrign(arg)
   assert max(z[0].lo,c.lo)<=min(z[0].hi,c.hi) and max(z[1].lo,s.lo)<=min(z[1].hi,s.hi)
   nn=cnorm2(z);assert nn.lo<=SCALE<=nn.hi
 print('PASS: odd and even unit roots agree with an independent rational-center Taylor enclosure')

def normalize_grid(t,N,n):
 j=t[0]//(N//n)
 return tuple((v-j*(N//n)*(k+1))%N for k,v in enumerate(t))

def grid_representative(t,N,n):
 neg=tuple(-v%N for v in t)
 return min(normalize_grid(v,N,n) for v in (t,t[::-1],neg,neg[::-1]))

def initial_grid(n):
 N=2*n;d=n-1
 for rest in itertools.product(range(N),repeat=d-1):
  for first in range(2):
   t=(first,)+rest
   if t==grid_representative(t,N,n):yield t

def initial_orbit_count(n):
 N=2*n
 if n%2:total=N**(n-1)+n*2**(n-1)+(n+1)*N**((n-1)//2)
 else:total=N**(n-1)+n*2**(n-1)+(n//2)*N**(n//2)+4*N**((n-2)//2)
 assert total%(4*n)==0
 return total//(4*n)

def phase_atlas(n,root,item,BI,R):
 m=n+1;d=n-1;p=[(root[k],ZERO if k<2 else root[m+k-2]) for k in range(m)]
 args=[ZERO,ZERO]
 for a,num in zip(p[2:],item['phase'][2:]):
  unit=crealmul(a,ONE/cnorm2(a).sqrt());a0=qi(num,10**15);sn,cs=itrign(a0);dist=cnorm2(csub(unit,(cs,sn))).sqrt()
  assert dist.hi<qi(1,10**6).lo
  args.append(a0+I(-2*dist.hi,2*dist.hi))
 base=[-args[k]+qi(k,n)*args[n] for k in range(1,n)]
 atlas=[]
 for rev in (False,True):
  bb=base[::-1] if rev else base
  for sign in (1,-1):
   for twist in range(n):atlas.append(([qi(sign)*v+qi(2*twist*k,n)*exact_pi() for k,v in enumerate(bb,1)],rev))
 boxsq=max(sum(sum(BI[i][j]*s[j] for j in range(d))**2 for i in range(d)) for s in itertools.product((-1,1),repeat=d))
 return atlas,ri(boxsq).sqrt(),[[ri(v) for v in row] for row in BI],ri(R)

def inside_atomic(n,level,t,atlas,boxnorm,BI,R):
 N=2*n if level==0 else 2*n*2**(level+1);half=exact_pi()/qi(2*n*2**level);two_pi=qi(2)*exact_pi();piv=exact_pi()
 point=[qi(2*v,N)*piv for v in t]
 for center,rev in atlas:
  delta=[]
  for x,y in zip(point,center):
   z=x-y;mid=(z.lo+z.hi)//2;period=(two_pi.lo+two_pi.hi)//2;k=(2*mid+period)//(2*period);z=z-two_pi*qi(k)
   if z.lo<=-piv.lo or z.hi>=piv.lo:break
   delta.append(z)
  if len(delta)<n-1:continue
  if rev:delta=delta[::-1]
  yy=rmatvec(BI,delta);distance=inormsq(yy).sqrt()+half*boxnorm
  if distance.hi<R.lo:return True
 return False

def exact_global(n,events,root,C,item,BI,bounds,expected=None,node_atlas=None):
 N0=2*n;d=n-1;atlas,boxnorm,BII,R=phase_atlas(n,root,item,BI,bounds['R'])
 counts=[0,0,0,0,0];position=0;maxlevel=0;minpivot=None
 @lru_cache(256)
 def interpolation_inverse(index):
  assert node_atlas is not None and 0<=index<len(node_atlas)
  den,nodes=node_atlas[index]
  assert isinstance(den,int) and den>0 and len(nodes)==n+1 and nodes==sorted(set(nodes)) and all(0<=j<den for j in nodes)
  zz=[general_root(den,j) for j in nodes];ann=[(ONE,ZERO)]
  for z in zz:ann=cconv(ann,[(-z[0],-z[1]),(ONE,ZERO)])
  rows=[]
  for z in zz:
   quo=[(ZERO,ZERO)]*(n+1);quo[n]=ann[n+1]
   for k in range(n,0,-1):quo[k-1]=cadd(ann[k],cmul(z,quo[k]))
   derivative=(ZERO,ZERO)
   for value in reversed(quo):derivative=cadd(cmul(derivative,z),value)
   rows.append([cdivide(value,derivative) for value in quo])
  return rows
 @lru_cache(None)
 def threshold(level):return C*general_root(2*N0*2**level,1)[0]
 def visit(level,t):
  nonlocal position,maxlevel,minpivot
  assert 0<=level<=12 and position<len(events)
  rec=events[position];position+=1;maxlevel=max(maxlevel,level)
  N=N0 if level==0 else N0*2**(level+1);phase=(0,)+t+(0,);cap=threshold(level)
  assert cap.lo>0
  if isinstance(rec,int):
   assert rec in (0,1,2)
   if rec==0:
    mass=ZERO
    for j in range(n):
     z=(ONE,ZERO)
     for k in range(1,n):z=cadd(z,general_root(N,(t[k-1]-N//n*j*k)%N))
     mass=mass+cnorm2(z).sqrt()/qi(n)
    assert mass.hi<cap.lo,('DFT leaf',n,level,t,mass.lo,mass.hi,cap.lo)
    counts[0]+=1;return
   if rec==1:
    assert inside_atomic(n,level,t,atlas,boxnorm,BII,R),('local leaf',n,level,t)
    counts[1]+=1;return
   counts[3]+=1;factor=4 if level==0 else 2;NN=N0*2**(level+2)
   for bits in itertools.product((-1,1),repeat=d):visit(level+1,tuple((factor*v+bit)%NN for v,bit in zip(t,bits)))
   return
  if isinstance(rec,list) and len(rec)==2 and rec[0]==-1:
   bb=[general_root(N,j) for j in phase];VV=interpolation_inverse(rec[1]);mass=ZERO
   for row in VV:mass=mass+cnorm2(csum(cmul(x,y) for x,y in zip(row,bb))).sqrt()
   assert mass.hi<cap.lo,('interpolation leaf',n,level,t,rec[1],mass.lo,mass.hi,cap.lo)
   counts[4]+=1;return
  assert isinstance(rec,list) and len(rec)==2*n and all(isinstance(v,int) for v in rec)
  diagonal=I(cap.lo).square()-ONE;M=[[(diagonal if i==j else ZERO,ZERO) for j in range(n+1)] for i in range(n+1)]
  moments=[(qi(rec[2*j],10**12),qi(rec[2*j+1],10**12)) for j in range(n)]
  for i in range(n+1):
   for j in range(i+1,n+1):M[i][j]=csub(moments[j-i-1],general_root(N,(phase[j]-phase[i])%N));M[j][i]=cconj(M[i][j])
  assert interval_positive(M),('Toeplitz leaf',n,level,t)
  counts[2]+=1
 for roots,t in enumerate(initial_grid(n),1):
  visit(0,t)
  if roots%25000==0:print('Verified degree',n,'initial orbits',roots,'records',position,flush=True)
 assert position==len(events)
 assert roots==initial_orbit_count(n)
 assert sum(counts)==roots+(2**d)*counts[3]
 if expected is not None:assert (roots,counts,maxlevel)==expected
 print('PASS: COMPLETE GLOBAL COVER degree',n,'initial orbits',roots,'DFT/local/PSD/branch/interpolation',counts,'depth',maxlevel,'nodes',position)
 print('EXACT GLOBAL CONCLUSION: S_%d = C_%d'%(n,n))
 return roots,counts,maxlevel


