def main():
    start = time.monotonic()
    audit_general_roots()
    audit_real_dual_psd()
    audit_deficient_stationarity()
    expected = {
        6: (10616, [8653, 985, 37, 467, 15418], 7),
        7: (269712, [220856, 12949, 0, 2946, 221505], 7),
    }
    for n, events, nodes in (
        (6, COVER_EVENTS_6, NODE_ATLAS_6),
        (7, COVER_EVENTS_7, NODE_ATLAS_7),
    ):
        item, rootitem = ATOM_DATA[str(n)], ROOT_DATA[str(n)]
        root, b, C, BB, BI, bounds = atom_certificate(n, item, rootitem)
        assert algebraic_box(n, root, rootitem) == ALGEBRAIC_BOX_DATA[str(n)]
        verify_reversal_symmetry(n, root, rootitem['point'], rootitem['beta'])
        bracket = ((23625633426471608, 23625633426471609) if n == 6
                   else (25516580617664311, 25516580617664312))
        assert qi(bracket[0], 10**16).hi < C.lo < C.hi < qi(bracket[1], 10**16).lo
        print('C_%d exact enclosure numerators / 10^50:' % n, C.lo, C.hi, flush=True)
        exact_global(n, events, root, C, item, BI, bounds, expected[n], nodes)
    print('ALL EXACT FINITE CHECKS PASSED: S_6=C_6 and S_7=C_7.')
    print('The report proves the global implications and the two-orbit extremizer classification.')
    print('Elapsed seconds:', round(time.monotonic() - start, 3))


if __name__ == '__main__':
    main()
